D={
83059:("Causative have","**Have + objeto + particípio**: outra pessoa faz o serviço para você.",[("I {{had my suit made}} by a tailor.","Mandei fazer meu terno por um alfaiate."),("She {{has her hair cut}} every month.","Ela corta o cabelo todo mês (no salão)."),("We'll {{have the roof repaired}}.","Mandaremos consertar o telhado."),("He {{had his car stolen}}.","Roubaram o carro dele.")],"Qual indica que outra pessoa fez o serviço?",["I made my suit.","I had my suit made.","I make suits."],1,"Have + objeto + particípio."),
83060:("get / make / let","**Get someone to + base** (convencer); **make someone + base** (obrigar); **let someone + base** (permitir).",[("I'll {{get him to help}}.","Vou convencê-lo a ajudar."),("She {{made him apologize}}.","Ela o obrigou a pedir desculpas."),("They {{let us leave}}.","Eles nos deixaram sair."),("He {{was made to}} wait.","Fizeram-no esperar.")],"Na passiva, make pede…",["to + base","base sem to","-ing"],0,"Was made to wait."),
83061:("Passivo na ciência","Nos métodos, a **passiva** foca no processo, não em quem o fez.",[("Samples {{were collected}} daily.","As amostras foram coletadas diariamente."),("The data {{was analyzed}} carefully.","Os dados foram analisados com cuidado."),("Temperatures {{were recorded}} hourly.","As temperaturas foram registradas de hora em hora."),("The mixture {{was heated}} to 80°C.","A mistura foi aquecida a 80 °C.")],"Por que a passiva na ciência?",["foca o processo","dá ordem","mostra emoção"],0,"Foco no método."),
940013:("the elephant in the room","**The elephant in the room** = assunto óbvio evitado; **sit on the fence**; **burn bridges**; **jump on the bandwagon**; **rub salt in the wound**.",[("We must address {{the elephant in the room}}.","Precisamos tratar do assunto que todos evitam."),("Don't {{sit on the fence}}.","Não fique em cima do muro."),("Never {{burn bridges}}.","Nunca queime pontes."),("Why {{rub salt in the wound}}?","Por que piorar a dor?")],"“Sit on the fence” =",["não escolher lado","sentar numa cerca","vigiar"],0,"Neutro."),
83062:("Passivo com ou sem agente","**By + agente** só quando é informativo.",[("The jewels {{were stolen}}.","As joias foram roubadas."),("The jewels were stolen {{by a famous thief}}.","As joias foram roubadas por um ladrão famoso."),("The letter {{was sent}} yesterday.","A carta foi enviada ontem."),("It was painted {{by Monet}}.","Foi pintado por Monet.")],"Quando usar o agente?",["quando é informação útil","sempre","nunca"],0,"Útil."),
83063:("get-passive","**Get + particípio**: informal, geralmente algo inesperado ou desagradável.",[("He {{got arrested}}.","Ele foi preso."),("The window {{got damaged}}.","A janela se danificou."),("I {{got caught}} in the rain.","Fui pego pela chuva."),("They {{got married}} in June.","Eles se casaram em junho.")],"“Get-passive” soa…",["informal","muito formal","errado"],0,"Informal."),
83064:("Passivo formal","A passiva soa objetiva em textos formais: **has been + particípio**, **must be**, **is being**.",[("A new law {{has been proposed}}.","Uma nova lei foi proposta."),("The report {{must be submitted}} by Friday.","O relatório deve ser entregue até sexta."),("The plan {{is being considered}}.","O plano está sendo considerado."),("Applications {{will be reviewed}}.","As candidaturas serão analisadas.")],"“Is being considered” indica…",["processo em andamento","algo terminado","uma ordem"],0,"Em andamento."),
83065:("Modais na passiva","**Modal + be + particípio**; passado: **modal + have been + particípio**.",[("All work {{must be done}} on time.","Todo trabalho deve ser feito no prazo."),("The past {{can't be changed}}.","O passado não pode ser mudado."),("The form {{should be signed}}.","O formulário deve ser assinado."),("It {{might have been lost}}.","Pode ter sido perdido.")],"Qual está certa?",["It can fixed.","It can be fixed.","It can be fix."],1,"Can be + particípio."),
940014:("termos jurídicos","**Felony** (crime grave), **misdemeanor** (contravenção), **perjury** (mentir sob juramento), **indict**, **arraign**.",[("He was charged with a {{felony}}.","Ele foi acusado de um crime grave."),("It's only a {{misdemeanor}}.","É só uma contravenção."),("Lying under oath is {{perjury}}.","Mentir sob juramento é perjúrio."),("He was {{indicted}} yesterday.","Ele foi indiciado ontem.")],"“Perjury” =",["perjúrio","prisão","fiança"],0,"Mentir sob juramento."),
83066:("need + -ing","Com **need**, dois jeitos de sentido passivo: *The grass needs cutting* = *needs to be cut*.",[("The grass {{needs cutting}}.","A grama precisa ser cortada."),("The grass {{needs to be cut}}.","A grama precisa ser cortada."),("My car {{needs washing}}.","Meu carro precisa ser lavado."),("I need to {{have it repaired}}.","Preciso mandar consertar.")],"“Needs cutting” =",["needs to be cut","needs to cut","cuts"],0,"Sentido passivo."),
83067:("Nominalização","Troque o verbo por **substantivo**: *discover → discovery*, *refuse → refusal*, *explain → explanation*.",[("The {{discovery}} of a planet made news.","A descoberta de um planeta virou notícia."),("Her {{refusal}} surprised us.","A recusa dela nos surpreendeu."),("His {{explanation}} was clear.","A explicação dele foi clara."),("The {{increase}} in prices worried us.","O aumento dos preços nos preocupou.")],"Qual é o substantivo de “refuse”?",["refusal","refusing","refused"],0,"Refusal."),
83068:("Ativa × passiva","**Ativa** diz quem fez; **passiva** foca no que foi feito.",[("The committee {{approved}} the plan.","O comitê aprovou o plano."),("The plan {{was approved}} by the committee.","O plano foi aprovado pelo comitê."),("Someone {{broke}} the window.","Alguém quebrou a janela."),("The window {{was broken}}.","A janela foi quebrada.")],"Quando preferir a ativa?",["quando quer dizer quem fez","quando o agente é desconhecido","sempre em ciência"],0,"Agente importante."),
83069:("Revisão: passiva","**is accused, was accused, has been accused, will be accused, is being accused, must be accused, to be accused, being accused**.",[("He {{is accused}} of fraud.","Ele é acusado de fraude."),("He {{has been accused}} twice.","Ele já foi acusado duas vezes."),("He {{will be accused}} soon.","Ele será acusado em breve."),("He hates {{being accused}}.","Ele odeia ser acusado.")],"Qual está em andamento?",["is being accused","was accused","has accused"],0,"Is being."),
83070:("Orações participiais","**-ing** (ação simultânea); **having + particípio** (anterior); **-ed** (passivo).",[("{{Walking}} home, he met a friend.","Voltando para casa, ele encontrou um amigo."),("{{Having finished}}, I left.","Tendo terminado, saí."),("{{Delighted}} by the news, they cheered.","Encantados com a notícia, eles vibraram."),("{{Not knowing}} what to say, he stayed silent.","Sem saber o que dizer, ele ficou em silêncio.")],"“Having finished” indica…",["ação anterior","ação simultânea","ação futura"],0,"Anterior."),
940015:("persuadir","**I'd urge you to… Wouldn't you agree?** *Win over*, *coax*, *cajole*, *wheedle*.",[("{{I'd urge you to}} reconsider.","Eu o instaria a reconsiderar."),("{{Wouldn't you agree}}?","Você não concordaria?"),("Let me {{win you over}}.","Deixe-me conquistar você."),("She {{cajoled}} him into helping.","Ela o convenceu com lisonja a ajudar.")],"“Win over” =",["conquistar","ganhar sobre","perder"],0,"Conquistar."),
83071:("Relativas reduzidas","Corte **who/which + be**: *The girl standing there*; *The letter written by her*.",[("The girl {{standing}} there is my sister.","A garota parada ali é minha irmã."),("The letter {{written}} by her is old.","A carta escrita por ela é antiga."),("People {{living}} here pay less.","Pessoas que moram aqui pagam menos."),("The house {{built}} in 1900 is huge.","A casa construída em 1900 é enorme.")],"Use -ing para…",["sentido ativo","sentido passivo","negativas"],0,"Ativo."),
83072:("Relativas não restritivas","Informação extra **entre vírgulas**: *Milton, who was blind, wrote the poem.*",[("Milton, {{who was blind}}, wrote the poem.","Milton, que era cego, escreveu o poema."),("The poem, {{which is very long}}, is famous.","O poema, que é muito longo, é famoso."),("My mother, {{whose}} car is red, is late.","Minha mãe, cujo carro é vermelho, está atrasada."),("Paris, {{where}} I live, is lovely.","Paris, onde moro, é linda.")],"Em não restritivas não se usa…",["that","who","which"],0,"That."),
83073:("Preposição + whom/which","Em textos formais, a preposição vem **antes** do pronome.",[("The man {{to whom}} I spoke is a doctor.","O homem com quem falei é médico."),("The room {{in which}} we met was small.","A sala em que nos encontramos era pequena."),("The reason {{for which}} he left is unknown.","O motivo pelo qual ele saiu é desconhecido."),("The people {{with whom}} I work are kind.","As pessoas com quem trabalho são gentis.")],"Qual é mais formal?",["The man to whom I spoke","The man who I spoke to","The man I spoke to"],0,"Preposição antes."),
83074:("whose / where / when","**Whose** = posse; **where** = lugar; **when** = tempo; **reason why** = motivo.",[("Dante, {{whose}} guide was Virgil, wrote it.","Dante, cujo guia era Virgílio, escreveu isso."),("This is the place {{where}} he began.","Este é o lugar onde ele começou."),("Remember the day {{when}} we met.","Lembre-se do dia em que nos conhecemos."),("That's the reason {{why}} he left.","Esse é o motivo pelo qual ele saiu.")],"“Whose” indica…",["posse","lugar","tempo"],0,"Posse."),
83075:("Quantificador + relativa","**Quantificador + of whom/which**: *ten men, two of whom were wounded*.",[("Ten men, {{two of whom}} were wounded, escaped.","Dez homens, dois dos quais feridos, escaparam."),("Many gifts, {{most of which}} were gold.","Muitos presentes, a maioria de ouro."),("Several friends, {{none of whom}} came.","Vários amigos, nenhum dos quais veio."),("Three books, {{all of which}} I read.","Três livros, todos os quais li.")],"Para pessoas, use…",["of whom","of which","of that"],0,"Whom."),
940016:("phase out / scale back","**Phase out** = eliminar aos poucos; **scale back** = reduzir; **wind down** = encerrar gradualmente; **tone down** = suavizar.",[("They are {{phasing out}} the branch.","Estão eliminando a filial aos poucos."),("We must {{scale back}} spending.","Devemos reduzir os gastos."),("The company is {{winding down}}.","A empresa está encerrando."),("Please {{tone down}} the language.","Por favor, suavize a linguagem.")],"“Wind down” =",["encerrar gradualmente","enrolar","acelerar"],0,"Gradual."),
83076:("which para a frase toda","**Which** pode comentar uma **frase inteira**: *He failed, which surprised everyone.*",[("He failed the exam, {{which}} surprised everyone.","Ele reprovou na prova, o que surpreendeu todos."),("She won the prize, {{which}} made us proud.","Ela ganhou o prêmio, o que nos deixou orgulhosos."),("It rained all day, {{which}} ruined the picnic.","Choveu o dia todo, o que arruinou o piquenique."),("He lied, {{which}} was unfair.","Ele mentiu, o que foi injusto.")],"“Which” aqui se refere a…",["a frase inteira","um substantivo","uma pessoa"],0,"Frase inteira."),
83077:("Apostos","**Aposto** renomeia ou explica, entre vírgulas.",[("Lydgate, {{a young surgeon}}, arrived.","Lydgate, um jovem cirurgião, chegou."),("London, {{the capital of England}}, is huge.","Londres, a capital da Inglaterra, é enorme."),("My brother, {{a chef}}, cooked.","Meu irmão, um chef, cozinhou."),("Mr. Lee, {{our boss}}, resigned.","O Sr. Lee, nosso chefe, renunciou.")],"O aposto…",["pode ser removido sem quebrar a frase","é obrigatório","não leva vírgula"],0,"Removível."),
83078:("Construções absolutas","**Sujeito próprio + particípio**, sem verbo conjugado: *Weather permitting, we'll sail.*",[("{{Weather permitting}}, we'll sail tomorrow.","Se o tempo permitir, navegaremos amanhã."),("{{Everything considered}}, it was a good trip.","Considerando tudo, foi uma boa viagem."),("{{Time allowing}}, we'll visit the museum.","Se der tempo, visitaremos o museu."),("{{All things being equal}}, I'd choose it.","Em igualdade de condições, eu escolheria.")],"“Weather permitting” =",["se o tempo permitir","enquanto chove","apesar do tempo"],0,"Condição."),
83079:("Frases longas","Ache o **sujeito e o verbo principal** primeiro; depois veja as subordinadas.",[("{{Although it was late}}, we kept working.","Embora fosse tarde, continuamos trabalhando."),("Principal: {{we kept working}}.","Oração principal: continuamos trabalhando."),("{{Which I found}} hard to believe, he left.","O que achei difícil de acreditar: ele saiu."),("{{When she arrived}}, we began.","Quando ela chegou, começamos.")],"O que achar primeiro?",["sujeito e verbo principal","o último verbo","o adjetivo"],0,"Estrutura."),
940017:("bear in mind","**Bear in mind** = ter em mente; **lose track of**; **make allowances for**; **take advantage of**.",[("{{Bear in mind}} that prices change.","Tenha em mente que os preços mudam."),("I {{lost track of}} time.","Perdi a noção do tempo."),("{{Make allowances for}} his age.","Seja compreensivo com a idade dele."),("Don't {{take advantage of}} her.","Não se aproveite dela.")],"“Lose track of” =",["perder a noção","perder o trilho","perder o rastro"],0,"Perder a noção."),
83080:("Comparativos avançados","**The more … the more**; **twice as … as**; **by far** reforça superlativo.",[("{{The more}} he searched, {{the angrier}} he became.","Quanto mais procurava, mais irritado ficava."),("It's {{twice as long as}} the boat.","É duas vezes mais comprido que o barco."),("It's {{by far}} the best.","É de longe o melhor."),("Prices are {{nowhere near}} as high.","Os preços nem de longe são tão altos.")],"“By far the best” =",["de longe o melhor","um dos melhores","quase o melhor"],0,"Reforça."),
83081:("very × absolutely","Adjetivos **graduáveis**: very/quite/rather. **Extremos**: absolutely/completely/utterly.",[("It's {{very}} cold.","Está muito frio."),("It's {{absolutely}} freezing.","Está absolutamente congelante."),("I'm {{completely}} exhausted.","Estou completamente exausto."),("It's {{quite}} good.","É bastante bom.")],"Qual está certa?",["very freezing","absolutely freezing","absolutely cold"],1,"Extremo + absolutely."),
83082:("Quantificadores avançados","**A great deal of** (incontável); **a handful of** (contável); **hardly any**; **plenty of**; **scarce**.",[("A {{great deal of}} effort was needed.","Foi preciso muito esforço."),("A {{handful of}} people came.","Um punhado de pessoas veio."),("There's {{hardly any}} time.","Quase não há tempo."),("We have {{plenty of}} food.","Temos bastante comida.")],"“Hardly any” tem sentido…",["quase nenhum","muito","suficiente"],0,"Quase nenhum."),
83083:("a / the / sem artigo","**A/an** na primeira menção; **the** quando se sabe qual; **the** com únicos; **sem artigo** com plurais gerais.",[("There is {{a}} fly in my soup.","Há uma mosca na minha sopa."),("{{The}} fly is dead.","A mosca está morta."),("{{The}} sun rises in {{the}} east.","O sol nasce no leste."),("{{Dogs}} are loyal.","Cães são leais.")],"Qual está certa?",["The life is hard.","Life is hard.","A life is hard."],1,"Generalização: sem artigo."),
83084:("Pronomes claros","Todo pronome deve apontar para **um só substantivo**; *they/their* para pessoa geral.",[("Anna told Lia, “{{I'm}} late.”","Anna disse a Lia: “Estou atrasada.”"),("Everyone should bring {{their}} pen.","Todos devem trazer a própria caneta."),("The boss told Ben that {{Ben}} was wrong.","O chefe disse a Ben que Ben estava errado."),("When Mia met Eva, {{Mia}} smiled.","Quando Mia encontrou Eva, Mia sorriu.")],"“Anna told Lia she was late” é…",["ambíguo","claro","errado gramaticalmente"],0,"Quem?"),
940018:("look forward to + -ing","**Look forward to, object to, be committed to, resort to**: o *to* é preposição → **-ing**.",[("I {{look forward to seeing}} you.","Aguardo ver você."),("She {{objects to being}} interrupted.","Ela se opõe a ser interrompida."),("We're {{committed to improving}}.","Estamos comprometidos em melhorar."),("They {{resorted to using}} force.","Eles recorreram ao uso de força.")],"Qual está certa?",["look forward to see","look forward to seeing","look forward see"],1,"To + -ing."),
83085:("make × do","**Make**: criar (*a decision, an effort, progress, a mistake*). **Do**: tarefas (*a favor, your best, the housework*).",[("We must {{make a decision}}.","Precisamos tomar uma decisão."),("Please {{do me a favor}}.","Por favor, faça-me um favor."),("He {{makes an effort}} daily.","Ele se esforça diariamente."),("Let's {{do the housework}}.","Vamos fazer o serviço de casa.")],"Qual combina com “favor”?",["make a favor","do a favor","take a favor"],1,"Do a favor."),
83086:("Participiais: revisão","**-ing** (ativo, simultâneo); **not + -ing**; **-ed** (passivo/estado); **having + -ed** (anterior).",[("{{Sitting}} by the window, she read.","Sentada à janela, ela lia."),("{{Not knowing}} what to say, he stayed silent.","Sem saber o que dizer, ficou em silêncio."),("{{Delighted}} by the news, they cheered.","Encantados com a notícia, vibraram."),("{{Having finished}}, I left.","Tendo terminado, saí.")],"Qual mostra ação anterior?",["Sitting","Having finished","Delighted"],1,"Having + -ed."),
83087:("Particípios que ligam ideias","O particípio dá **motivo ou momento**: *Being alone, he felt afraid. On arriving, they unpacked.*",[("{{Being alone}}, he felt afraid.","Por estar sozinho, ele sentiu medo."),("{{On arriving}}, they unpacked.","Ao chegarem, desfizeram as malas."),("{{Not wanting to argue}}, she left.","Sem querer discutir, ela saiu."),("{{While waiting}}, I read.","Enquanto esperava, li.")],"“On arriving” =",["ao chegar","antes de chegar","sem chegar"],0,"Ao chegar."),
83088:("Graus de certeza","**Must be** (quase certeza); **can't be** (quase certeza do contrário); **may/might be** (possível).",[("That {{must be}} her car.","Esse deve ser o carro dela."),("He {{can't be}} serious.","Ele não pode estar falando sério."),("It {{may be}} true.","Pode ser verdade."),("She {{might be}} late.","Ela talvez se atrase.")],"Qual expressa mais certeza?",["might be","may be","must be"],2,"Must be."),
83089:("Deduzir o passado","**Must have + particípio** (quase certeza); **can't have** (quase certeza do contrário); **might have** (possível).",[("He {{must have forgotten}}.","Ele deve ter esquecido."),("She {{can't have left}}.","Ela não pode ter saído."),("It {{might have been}} a mistake.","Pode ter sido um erro."),("They {{must have known}}.","Eles devem ter sabido.")],"“Can't have left” =",["é impossível que tenha saído","pode ter saído","saiu"],0,"Impossível."),
940019:("gírias de games","**Nerf** enfraquece; **buff** fortalece; **respawn**; **grind**; **noob**; **gg**.",[("They {{nerfed}} the healer.","Enfraqueceram o curandeiro."),("I {{respawn}} for loot.","Renasço para pegar itens."),("Don't be a {{noob}}.","Não seja novato."),("{{GG}}, everyone!","Boa partida, pessoal!")],"“Grind” =",["repetir para evoluir","moer","brigar"],0,"Repetir tarefa."),
83090:("Modais contínuos","**Must be + -ing** (presente); **may/might/must have been + -ing** (passado em andamento).",[("He {{must be working}} late.","Ele deve estar trabalhando até tarde."),("She {{can't be joking}}.","Ela não pode estar brincando."),("They {{may have been waiting}} outside.","Podem ter ficado esperando lá fora."),("He {{must have been sleeping}}.","Ele devia estar dormindo.")],"“Must have been sleeping” =",["devia estar dormindo","deve dormir","dormirá"],0,"Dedução no passado."),
83091:("should have / ought to have","**Should have + particípio** lamenta o que não foi feito; **needn't have** = fez sem necessidade.",[("You {{should have listened}} to her.","Você devia tê-la ouvido."),("He {{ought to have known}} better.","Ele devia ter sabido."),("You {{needn't have waited}}.","Você não precisava ter esperado."),("We {{shouldn't have gone}}.","Não devíamos ter ido.")],"“Needn't have” =",["fez sem precisar","não fez","devia ter feito"],0,"Desnecessário."),
83092:("Obrigação no passado e futuro","**Had to** (passado); **will have to** (futuro); presente: have to / must.",[("He {{had to}} leave Paris.","Ele teve de deixar Paris."),("We {{will have to}} change our plans.","Teremos de mudar nossos planos."),("You {{don't have to}} come.","Você não precisa vir."),("You {{mustn't}} come.","Você não deve vir.")],"“Don't have to” × “mustn't”:",["não precisa × proibido","proibido × não precisa","iguais"],0,"Diferença."),
83093:("Permitido e proibido","**Be allowed / permitted to** (permitido); **be prohibited / may not** (proibido).",[("Children {{are allowed to}} play outside.","As crianças podem brincar fora."),("Smoking {{is prohibited}}.","É proibido fumar."),("You {{may not}} enter.","Você não pode entrar."),("Visitors {{are permitted to}} take photos.","Visitantes podem tirar fotos.")],"“May not” indica…",["proibição","permissão","dúvida"],0,"Proibição."),
940020:("cut corners","**Cut corners** = fazer de qualquer jeito; **drag your feet**; **pull your weight**; **toe the line**.",[("We don't {{cut corners}}.","Não fazemos de qualquer jeito."),("Stop {{dragging your feet}}.","Pare de fazer corpo mole."),("Everyone must {{pull their weight}}.","Todos devem fazer a sua parte."),("He always {{toes the line}}.","Ele sempre segue as regras.")],"“Drag your feet” =",["fazer corpo mole","arrastar os pés","andar rápido"],0,"Demorar de propósito."),
83094:("could / was able to / managed to","**Could** = capacidade geral; **was able to / managed to** = ação específica que deu certo.",[("He {{could swim}} when he was five.","Ele sabia nadar aos cinco."),("They {{managed to fix}} the filter.","Eles conseguiram consertar o filtro."),("She {{was able to}} escape.","Ela conseguiu escapar."),("I {{succeeded in}} finishing.","Consegui terminar.")],"Qual é conquista específica?",["He could swim.","They managed to fix it.","She could read."],1,"Managed to."),
83095:("could have / might have: críticas","**Could / might have + particípio** criticam o que não foi feito.",[("You {{could have told}} me!","Você poderia ter me contado!"),("He {{might have called}} first.","Ele podia ter ligado antes."),("You {{could at least}} say sorry.","Você poderia ao menos pedir desculpas."),("She {{might have}} helped.","Ela podia ter ajudado.")],"O tom é de…",["reclamação","elogio","pergunta"],0,"Reclamação."),
83096:("Especular sobre o futuro","**May/might well**, **be bound to**, **be likely to**.",[("It {{may well}} rain.","Pode muito bem chover."),("She {{is bound to}} win.","Ela com certeza vai ganhar."),("He {{is likely to}} arrive late.","Ele provavelmente chegará tarde."),("It {{might well}} be true.","Pode muito bem ser verdade.")],"“Bound to” =",["quase certo","proibido","preso"],0,"Certeza."),
83097:("Modais polidos","**I was wondering if you could… Would you mind…? Could we…? I'd be very grateful if…**",[("{{I was wondering if}} you could help.","Eu me perguntava se você poderia ajudar."),("{{Would you mind opening}} the window?","Você se importaria de abrir a janela?"),("{{Could we reschedule}} the meeting?","Poderíamos remarcar a reunião?"),("{{I'd be very grateful if}} you replied.","Ficaria muito grato se respondesse.")],"Qual é o mais indireto?",["Open the window.","Would you mind opening the window?","You open it."],1,"Mais polido."),
83098:("dare e need","**Dare** e **need** como modais (negativas/perguntas): *I daren't tell him. You needn't come.*",[("I {{daren't tell}} him.","Não ouso contar a ele."),("You {{needn't come}}.","Você não precisa vir."),("{{How dare you}}!","Como você ousa!"),("I don't {{dare to}} ask.","Não ouso perguntar.")],"Após modal needn't vem…",["base sem to","to + base","-ing"],0,"Base."),
940021:("weed out / single out","**Weed out** = eliminar; **filter out**; **single out** = destacar; **whittle down** = reduzir aos poucos.",[("We {{weed out}} poor candidates.","Eliminamos candidatos fracos."),("They {{singled out}} the best.","Destacaram o melhor."),("We {{whittled down}} the list.","Reduzimos a lista aos poucos."),("{{Filter out}} the noise.","Filtre o ruído.")],"“Single out” =",["destacar","isolar um sol","separar dois"],0,"Escolher entre vários."),
83099:("Modais no discurso indireto","Recuo: **can → could**, **will → would**, **must → had to**.",[("He said he {{could}} help us.","Ele disse que podia nos ajudar."),("She said she {{would}} call later.","Ela disse que ligaria depois."),("They said we {{had to}} leave.","Disseram que tínhamos de sair."),("He said it {{might}} rain.","Ele disse que podia chover.")],"“Must” no discurso indireto vira…",["had to","musted","can"],0,"Had to."),
83100:("may as well / had better / would rather","**May as well** = já que é assim, bem podemos; **had better**; **would rather**. Todos + base.",[("We {{may as well}} go home.","Bem podemos ir para casa."),("You {{had better}} hurry.","É melhor você se apressar."),("I {{would rather}} stay in.","Prefiro ficar em casa."),("You {{might as well}} try.","Você bem pode tentar.")],"“May as well” =",["bem podemos","talvez bem","não podemos"],0,"Resignação."),
83101:("Dúvida e certeza","**Bound to / certain to** (certeza); **doubt** (dúvida); **unlikely** (pouca chance).",[("He is {{bound to}} win.","Ele certamente vai ganhar."),("I {{doubt}} that he will lose.","Duvido que ele perca."),("It is {{unlikely}} to rain.","É improvável que chova."),("She's {{certain to}} come.","Ela certamente virá.")],"“Unlikely” =",["improvável","provável","certo"],0,"Improvável."),
83102:("Conselhos com modais","**Might want to / could / should / would be wise to**: quanto mais forte o modal, mais firme o conselho.",[("You {{might want to}} wait.","Talvez você queira esperar."),("You {{should}} talk to her.","Você deveria conversar com ela."),("It {{would be wise to}} wait.","Seria sensato esperar."),("You {{could}} try again.","Você poderia tentar de novo.")],"Qual é o mais suave?",["You should wait.","You might want to wait.","You must wait."],1,"Might want to."),
83103:("suggest / recommend","Depois de **suggest, propose, recommend**: **-ing** ou **that + verbo simples**.",[("I {{suggest meeting}} on Monday.","Sugiro nos encontrarmos na segunda."),("I {{recommend that she apply}}.","Recomendo que ela se candidate."),("They {{proposed that he resign}}.","Propuseram que ele renunciasse."),("I {{urge you to}} reconsider.","Peço que você reconsidere.")],"Qual está certa?",["I suggest to meet.","I suggest meeting.","I suggest meet."],1,"Suggest + -ing."),
940022:("discordar com diplomacia","**I beg to differ. I see it differently. I take issue with…** com *with respect*.",[("{{I beg to differ}}.","Permita-me discordar."),("{{I see it differently}}.","Eu vejo de outro modo."),("{{I take issue with}} that.","Tenho objeções a isso."),("{{With respect}}, I disagree.","Com todo o respeito, discordo.")],"Qual discorda com diplomacia?",["You're wrong.","I beg to differ.","No!"],1,"I beg to differ."),
83104:("Modais: revisão","**Must have / can't have / might have** (passado); **may / must** (permissão/obrigação).",[("It {{must have been}} a mistake.","Deve ter sido um erro."),("He {{can't have known}}.","Ele não pode ter sabido."),("You {{may}} leave.","Você pode sair."),("You {{must}} sign here.","Você deve assinar aqui.")],"“Must have been” =",["dedução sobre o passado","obrigação","pedido"],0,"Dedução."),
83105:("Recuo de tempos","O verbo **recua**: presente → passado; passado → past perfect.",[("“I am tired.” → He said he {{was}} tired.","“Estou cansado.” → Ele disse que estava cansado."),("“I went there.” → He said he {{had been}} there.","“Fui lá.” → Ele disse que tinha ido lá."),("She said she {{had seen}} it.","Ela disse que tinha visto."),("They said they {{would}} come.","Disseram que viriam.")],"“I went” → He said he ___",["went","had gone","goes"],1,"Past perfect."),
83106:("Verbos de reporte","**Admit/deny/suggest + -ing**; **insist on + -ing**; **agree/promise/refuse + to**.",[("He {{admitted making}} a mistake.","Ele admitiu ter cometido um erro."),("She {{denied taking}} it.","Ela negou ter pegado."),("He {{insisted on voting}}.","Ele insistiu em votar."),("They {{agreed to wait}}.","Concordaram em esperar.")],"Qual está certa?",["He denied to take it.","He denied taking it.","He denied take it."],1,"Deny + -ing."),
83107:("Perguntas reportadas","Ordem de **afirmação**, sem do/does/did.",[("“Have you seen him?” → She asked {{whether I had seen}} him.","“Você o viu?” → Ela perguntou se eu o tinha visto."),("“Where do you live?” → He asked {{where I lived}}.","“Onde você mora?” → Ele perguntou onde eu morava."),("She asked {{if}} it was ready.","Ela perguntou se estava pronto."),("He asked {{what time it was}}.","Ele perguntou que horas eram.")],"Qual está certa?",["He asked where did I live.","He asked where I lived.","He asked where I live did."],1,"Ordem normal."),
940023:("adjetivo + preposição","**Keen on, prone to, oblivious to, immune to, fond of, allergic to, sensitive to**.",[("He's {{keen on}} chess.","Ele é apaixonado por xadrez."),("She's {{prone to}} headaches.","Ela é propensa a dores de cabeça."),("He seemed {{oblivious to}} the noise.","Ele parecia alheio ao barulho."),("I'm {{allergic to}} cats.","Sou alérgico a gatos.")],"“Fond of” =",["gostar de","longe de","cheio de"],0,"Gostar de."),
83108:("Ordens e pedidos reportados","**Told/asked/ordered + pessoa + to**; negativa: **not to**.",[("The officer {{ordered them to leave}}.","O oficial mandou que saíssem."),("She {{asked him to wait}}.","Ela pediu que ele esperasse."),("He {{warned us not to}} touch it.","Ele nos avisou para não tocar."),("They {{told me to}} sit.","Mandaram-me sentar.")],"“Don't enter!” → He warned us ___.",["to not enter","not to enter","don't enter"],1,"Not to."),
83109:("Resumir um discurso","Verbos formais: **stated, declared, emphasized, concluded**.",[("The president {{stated that}} the nation was united.","O presidente declarou que a nação estava unida."),("He {{emphasized that}} equality mattered.","Ele enfatizou que a igualdade importava."),("She {{concluded that}} more work was needed.","Ela concluiu que era preciso mais trabalho."),("They {{declared}} a holiday.","Declararam um feriado.")],"“Emphasize” =",["enfatizar","enfraquecer","esquecer"],0,"Enfatizar."),
83110:("Verbos de tom de voz","Em vez de *said*: **whispered, muttered, snapped** — mesmo recuo.",[("She {{whispered}} that it was a secret.","Ela sussurrou que era segredo."),("He {{muttered}} that he was tired.","Ele resmungou que estava cansado."),("She {{snapped}} that she didn't care.","Ela retrucou que não se importava."),("He {{sighed}} that it was late.","Ele suspirou que era tarde.")],"“Mutter” =",["resmungar","gritar","cochilar"],0,"Resmungar."),
83111:("Citar × parafrasear","**Citar** = palavras exatas entre aspas; **parafrasear** = suas palavras.",[("As Thoreau puts it, {{“simplify, simplify.”}}","Como diz Thoreau: “simplifique, simplifique.”"),("{{In other words}}, he wanted a simpler life.","Em outras palavras, ele queria uma vida mais simples."),("{{According to}} Thoreau, nature teaches.","Segundo Thoreau, a natureza ensina."),("He {{argues that}} less is more.","Ele argumenta que menos é mais.")],"Parafrasear é…",["usar suas próprias palavras","copiar","traduzir"],0,"Reescrever."),
83112:("Pensamentos reportados","**Thought, wondered, realized, decided** com o mesmo recuo.",[("“It is too late.” → She {{thought}} it {{was}} too late.","“É tarde demais.” → Ela achou que era tarde demais."),("She {{realized}} that she {{had made}} a mistake.","Ela percebeu que tinha cometido um erro."),("He {{wondered}} if it was true.","Ele se perguntou se era verdade."),("They {{decided}} to wait.","Decidiram esperar.")],"“Wonder” =",["perguntar-se","vencer","querer"],0,"Perguntar-se."),
940024:("supposing / providing / lest","**Supposing / assuming** imaginam; **providing** = desde que; **lest** = para que não (formal).",[("{{Supposing}} it fails?","E se falhar?"),("{{Providing}} we begin tonight, we'll finish.","Desde que comecemos hoje à noite, terminaremos."),("{{Assuming}} he's right, what then?","Supondo que ele esteja certo, e daí?"),("Be careful {{lest}} you fall.","Tenha cuidado para que não caia.")],"“Lest” =",["para que não","a menos que","porque"],0,"Para que não."),
83113:("Boatos","**Rumor has it that… Apparently… Reportedly… He is said to…**",[("{{Rumor has it that}} he is leaving.","Corre o boato de que ele vai embora."),("He {{is said to}} be rich.","Dizem que ele é rico."),("{{It is rumored that}} the shop will close.","Há boatos de que a loja fechará."),("{{Reportedly}}, it was empty.","Segundo relatos, estava vazio.")],"“Rumor has it” introduz…",["um boato","uma ordem","uma certeza"],0,"Boato."),
83114:("Futuro reportado","**Will → would**; **am/is/are going to → was/were going to**.",[("“I will return.” → She said she {{would}} return.","“Voltarei.” → Ela disse que voltaria."),("“We are going to leave.” → They said they {{were going to}} leave.","“Vamos sair.” → Disseram que iam sair."),("He said he {{would help}}.","Disse que ajudaria."),("She said it {{would rain}}.","Ela disse que choveria.")],"“Will” reportado vira…",["would","was","did"],0,"Would."),
83115:("Relatos mistos","Misture **afirmações** (that + recuo) e **perguntas** (ordem normal + recuo).",[("He said he {{was innocent}} and asked {{why they didn't believe}} him.","Ele disse que era inocente e perguntou por que não acreditavam nele."),("She said she was tired and asked {{if she could leave}}.","Ela disse que estava cansada e perguntou se podia sair."),("He explained that he {{had lost}} it.","Ele explicou que o tinha perdido."),("They asked {{where he was}}.","Perguntaram onde ele estava.")],"Perguntas reportadas usam ordem…",["normal","invertida","qualquer"],0,"Normal."),
83116:("Discurso indireto: revisão","**Afirmação** (said that + recuo); **pergunta** (ordem normal); **ordem** (told + pessoa + to).",[("He said he {{had seen}} the whale.","Ele disse que tinha visto a baleia."),("She asked where the whale {{was}}.","Ela perguntou onde estava a baleia."),("The captain {{told them to}} wait.","O capitão mandou que esperassem."),("He asked {{if}} it was real.","Ele perguntou se era real.")],"Qual é a ordem?",["He told us to wait.","He said wait.","He asked wait."],0,"Told + to."),
}
